/**
 * GENERATED brand assets (Dr. Pinguin graduation-cap penguin, pixel-art version), served by
 * server/middleware/brand-icons.ts. Favicons 16/32/48 are hand-tuned pixel sprites (no blur);
 * 180/192/512 are the 46x63 sprite scaled by whole numbers (nearest neighbour). /og-v2.jpg is the
 * 1200x630 share fallback card and /brand-poster-v2.jpg the 1280x720 poster fallback for videos without
 * a real thumbnail. Stored as base64 because the repo is updated through a text-only API.
 */
export type BrandIcon = { type: string; b64: string };

/** Share fallback card (1200x630). Real video thumbnails always win; this is only the fallback. */
export const BRAND_OG_PATH = "/og-v2.jpg";
/** Poster fallback (1280x720) for videos without a usable thumbnail. */
export const BRAND_POSTER_PATH = "/brand-poster-v2.jpg";

export const BRAND_ICONS: Record<string, BrandIcon> = {
  "/favicon.ico": { type: "image/x-icon", b64: "" },
  "/favicon-32.png": { type: "image/png", b64: "" },
  "/apple-touch-icon.png": { type: "image/png", b64: "" },
  "/icon-192.png": { type: "image/png", b64: "" },
  "/icon-512.png": { type: "image/png", b64: "" },
  "/icon-512-maskable.png": { type: "image/png", b64: "" },
  "/og-v2.jpg": { type: "image/jpeg", b64: "" },
  "/brand-poster-v2.jpg": { type: "image/jpeg", b64: "" },
};

const decodedAssets = new Map<string, Uint8Array>();

/** Decoded bytes of a bundled brand asset (memoised per isolate), or null for unknown paths. */
export function brandAssetBytes(path: string): Uint8Array | null {
  const icon = BRAND_ICONS[path];
  if (!icon) return null;
  let bytes = decodedAssets.get(path);
  if (!bytes) {
    const bin = atob(icon.b64);
    bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    decodedAssets.set(path, bytes);
  }
  return bytes;
}
